<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Database;
Auth::requirePermission('competitors.view');$pdo=Database::connection();
$q=trim((string)($_GET['q']??''));$type=(string)($_GET['type']??'');$status=(string)($_GET['status']??'');$style=(string)($_GET['style']??'');$level=(string)($_GET['level']??'');$event=(string)($_GET['event']??'');$category=(string)($_GET['category']??'');$complete=(string)($_GET['complete']??'');$sort=(string)($_GET['sort']??'name');$order=strtolower((string)($_GET['order']??'asc'))==='desc'?'DESC':'ASC';$perPage=in_array((int)($_GET['per_page']??50),[25,50,100,200,500],true)?(int)$_GET['per_page']:50;$page=max(1,(int)($_GET['page']??1));
$where=['1=1'];$params=[];
if($q!==''){$where[]="(LOWER(w.display_name) LIKE LOWER(:q1) OR LOWER(w.identity_code) LIKE LOWER(:q2) OR LOWER(COALESCE(NULLIF(w.country,''),c.country,'')) LIKE LOWER(:q3) OR EXISTS(SELECT 1 FROM bdc_wdc_registrations rq WHERE rq.wdc_identity_id=w.id AND rq.status='registered' AND (LOWER(rq.category_name) LIKE LOWER(:q4) OR LOWER(rq.event_name) LIKE LOWER(:q5))))";$like='%'.$q.'%';foreach(range(1,5) as $i)$params['q'.$i]=$like;}
if(in_array($type,['solo','couple','duo','pro_am','team'],true)){$where[]='w.entry_type=:type';$params['type']=$type;}if(in_array($status,['active','archived'],true)){$where[]='w.status=:status';$params['status']=$status;}
if(in_array($style,['salsa','bachata','other'],true)){$where[]="EXISTS(SELECT 1 FROM bdc_wdc_registrations rf WHERE rf.wdc_identity_id=w.id AND rf.status='registered' AND rf.dance_style=:style)";$params['style']=$style;}if(in_array($level,['open','amateur','intermediate','pro_am','professional'],true)){$where[]="EXISTS(SELECT 1 FROM bdc_wdc_registrations rl WHERE rl.wdc_identity_id=w.id AND rl.status='registered' AND rl.competition_level=:level)";$params['level']=$level;}
if($event!==''){$where[]="EXISTS(SELECT 1 FROM bdc_wdc_registrations re WHERE re.wdc_identity_id=w.id AND re.status='registered' AND re.event_key=:event)";$params['event']=$event;}if($category!==''){$where[]="EXISTS(SELECT 1 FROM bdc_wdc_registrations rc WHERE rc.wdc_identity_id=w.id AND rc.status='registered' AND rc.category_key=:category)";$params['category']=$category;}
if($complete==='missing_photo')$where[]="COALESCE(NULLIF(w.photo_url,''),NULLIF(c.photo_url,'')) IS NULL";elseif($complete==='missing_country')$where[]="COALESCE(NULLIF(w.country,''),NULLIF(c.country,'')) IS NULL";elseif($complete==='no_registration')$where[]="NOT EXISTS(SELECT 1 FROM bdc_wdc_registrations rn WHERE rn.wdc_identity_id=w.id AND rn.status='registered')";elseif($complete==='duplicate')$where[]="EXISTS(SELECT 1 FROM bdc_wdc_identities wd WHERE wd.id<>w.id AND wd.entry_type=w.entry_type AND wd.normalised_name=w.normalised_name AND wd.status='active')";
$whereSql=implode(' AND ',$where);$sortMap=['name'=>'w.display_name','wdc_id'=>'w.identity_code','type'=>'w.entry_type','country'=>'country_display','points'=>'championship_points','entries'=>'published_entries','status'=>'w.status','updated'=>'w.updated_at'];$orderBy=$sortMap[$sort]??$sortMap['name'];$sort=array_key_exists($sort,$sortMap)?$sort:'name';
$base="SELECT w.*,COALESCE(NULLIF(w.country,''),c.country) country_display,COALESCE(NULLIF(w.photo_url,''),NULLIF(c.photo_url,'')) photo_display,c.instagram,c.gender,c.id shared_person_id,COALESCE(p.championship_points,0) championship_points,COALESCE(p.published_entries,0) published_entries,COALESCE(reg.registration_count,0) registration_count,reg.registered_categories,reg.registered_events,(SELECT COUNT(*) FROM bdc_wdc_identities wd WHERE wd.id<>w.id AND wd.entry_type=w.entry_type AND wd.normalised_name=w.normalised_name AND wd.status='active') duplicate_count FROM bdc_wdc_identities w LEFT JOIN bdc_competitors c ON c.id=w.solo_competitor_id LEFT JOIN(SELECT wdc_identity_id,SUM(points) championship_points,COUNT(*) published_entries FROM bdc_wdc_championship_points GROUP BY wdc_identity_id)p ON p.wdc_identity_id=w.id LEFT JOIN(SELECT wdc_identity_id,COUNT(*) registration_count,GROUP_CONCAT(DISTINCT CONCAT(category_name,'|',dance_style,'|',competition_level) ORDER BY category_name SEPARATOR ';;') registered_categories,GROUP_CONCAT(DISTINCT event_name ORDER BY event_name SEPARATOR ';;') registered_events FROM bdc_wdc_registrations WHERE status='registered' GROUP BY wdc_identity_id)reg ON reg.wdc_identity_id=w.id WHERE {$whereSql}";
if(($_GET['export']??'')==='csv'){Auth::requireSuperAdmin();$s=$pdo->prepare($base." ORDER BY {$orderBy} {$order},w.id");$s->execute($params);header('Content-Type:text/csv; charset=UTF-8');header('Content-Disposition:attachment; filename="wdc-competitors-'.date('Y-m-d-His').'.csv"');$out=fopen('php://output','wb');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['WDC ID','Name','Entry Type','Country','Categories','Events','Championship Points','Published Entries','Status']);foreach($s->fetchAll() as $r)fputcsv($out,[$r['identity_code'],$r['display_name'],$r['entry_type'],$r['country_display'],$r['registered_categories'],$r['registered_events'],$r['championship_points'],$r['published_entries'],$r['status']]);fclose($out);exit;}
$count=$pdo->prepare("SELECT COUNT(*) FROM bdc_wdc_identities w LEFT JOIN bdc_competitors c ON c.id=w.solo_competitor_id WHERE {$whereSql}");$count->execute($params);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;$stmt=$pdo->prepare($base." ORDER BY {$orderBy} {$order},w.id LIMIT :limit OFFSET :offset");foreach($params as $k=>$v)$stmt->bindValue(':'.$k,$v);$stmt->bindValue(':limit',$perPage,PDO::PARAM_INT);$stmt->bindValue(':offset',$offset,PDO::PARAM_INT);$stmt->execute();$rows=$stmt->fetchAll();
$events=$pdo->query("SELECT DISTINCT event_key,event_name FROM bdc_wdc_registrations ORDER BY event_name")->fetchAll();$categories=$pdo->query("SELECT DISTINCT category_key,category_name FROM bdc_wdc_registrations ORDER BY category_name")->fetchAll();
$counts=['WDC identities'=>(int)$pdo->query("SELECT COUNT(*) FROM bdc_wdc_identities WHERE status='active'")->fetchColumn(),'Active registrations'=>(int)$pdo->query("SELECT COUNT(*) FROM bdc_wdc_registrations WHERE status='registered'")->fetchColumn(),'Bachata entries'=>(int)$pdo->query("SELECT COUNT(*) FROM bdc_wdc_registrations WHERE status='registered' AND dance_style='bachata'")->fetchColumn(),'Salsa entries'=>(int)$pdo->query("SELECT COUNT(*) FROM bdc_wdc_registrations WHERE status='registered' AND dance_style='salsa'")->fetchColumn(),'Missing photos'=>(int)$pdo->query("SELECT COUNT(*) FROM bdc_wdc_identities w LEFT JOIN bdc_competitors c ON c.id=w.solo_competitor_id WHERE w.status='active' AND COALESCE(NULLIF(w.photo_url,''),NULLIF(c.photo_url,'')) IS NULL")->fetchColumn(),'Possible duplicates'=>(int)$pdo->query("SELECT COUNT(*) FROM bdc_wdc_identities w WHERE w.status='active' AND EXISTS(SELECT 1 FROM bdc_wdc_identities d WHERE d.id<>w.id AND d.status='active' AND d.entry_type=w.entry_type AND d.normalised_name=w.normalised_name)")->fetchColumn()];
function dcq(array $changes=[]):string{$query=array_merge($_GET,$changes);foreach($query as $k=>$v)if($v===''||$v===null)unset($query[$k]);return'?'.http_build_query($query);}function dcsort(string $column,string $current,string $order):string{return dcq(['sort'=>$column,'order'=>$current===$column&&$order==='ASC'?'desc':'asc','page'=>1]);}function dclabel(?string $v):string{return ucwords(str_replace('_',' ',(string)$v));}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dance Cup Competitor</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="<?=e(url('public/assets/css/app.css'))?>" rel="stylesheet"><style>.summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:1rem}.photo{width:58px;height:68px;object-fit:cover;border-radius:10px;border:1px solid #dce3ec}.sortable{color:inherit;text-decoration:none}.category-stack{min-width:260px}.category-chip{display:block;border-left:3px solid #0d6efd;padding-left:.55rem;margin:.2rem 0}.actions{display:flex;gap:.35rem;flex-wrap:wrap}@media(max-width:767px){.actions{display:grid}.actions .btn{width:100%}}</style></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="<?=e(url('admin/'))?>">BDC Admin</a><a class="btn btn-outline-light btn-sm" href="<?=e(url('admin/dance-cup/'))?>">Dance Cup Scoring</a></div></nav><main class="container-fluid py-4" style="max-width:1700px"><div class="d-flex justify-content-between gap-3 flex-wrap mb-3"><div><h1 class="h3 mb-1">Dance Cup Competitor</h1><p class="text-muted mb-0">One permanent WDC identity with all registrations, results and profile actions.</p></div><div class="d-flex gap-2"><?php if(Auth::isSuperAdmin()):?><a class="btn btn-outline-success" href="<?=e(dcq(['export'=>'csv','page'=>null]))?>">Export CSV</a><a class="btn btn-outline-warning" href="<?=e(dcq(['complete'=>'duplicate','page'=>1]))?>">Review duplicates</a><?php endif;?><?php if(Auth::can('competitors.edit')):?><a class="btn btn-dark" href="competitor-edit.php">Add competitor</a><?php endif;?></div></div><section class="summary mb-4"><?php foreach($counts as $key=>$value):?><a class="card border-0 shadow-sm text-decoration-none text-dark" href="<?=$key==='Missing photos'?e(dcq(['complete'=>'missing_photo','page'=>1])):($key==='Possible duplicates'?e(dcq(['complete'=>'duplicate','page'=>1])):'#')?>"><div class="card-body"><div class="small text-muted"><?=e($key)?></div><strong class="fs-2"><?=$value?></strong></div></a><?php endforeach;?></section>
<form class="card border-0 shadow-sm mb-3"><div class="card-body row g-2"><div class="col-xl-4"><label class="form-label">Search</label><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Name, WDC ID, country, event or category"></div><?php foreach(['type'=>['Entry type',[''=>'All types','solo'=>'Solo','couple'=>'Couple','duo'=>'Duo','pro_am'=>'Pro Am','team'=>'Team']], 'style'=>['Dance style',[''=>'All styles','bachata'=>'Bachata','salsa'=>'Salsa','other'=>'Other']], 'level'=>['Level',[''=>'All levels','open'=>'Open','amateur'=>'Amateur','intermediate'=>'Intermediate','pro_am'=>'Pro Am','professional'=>'Professional']], 'status'=>['Status',[''=>'All statuses','active'=>'Active','archived'=>'Archived']], 'complete'=>['Completeness',[''=>'Any','missing_photo'=>'Missing photo','missing_country'=>'Missing country','no_registration'=>'No registration','duplicate'=>'Possible duplicate']]] as $name=>[$title,$options]):?><div class="col-6 col-xl"><label class="form-label"><?=e($title)?></label><select class="form-select" name="<?=$name?>"><?php foreach($options as $v=>$text):?><option value="<?=e($v)?>" <?=($$name===$v)?'selected':''?>><?=e($text)?></option><?php endforeach;?></select></div><?php endforeach;?><div class="col-md-6"><label class="form-label">Event</label><select class="form-select" name="event"><option value="">All events</option><?php foreach($events as $v):?><option value="<?=e($v['event_key'])?>" <?=$event===$v['event_key']?'selected':''?>><?=e($v['event_name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Category</label><select class="form-select" name="category"><option value="">All categories</option><?php foreach($categories as $v):?><option value="<?=e($v['category_key'])?>" <?=$category===$v['category_key']?'selected':''?>><?=e($v['category_name'])?></option><?php endforeach;?></select></div><div class="col-12 d-flex gap-2"><button class="btn btn-dark">Apply filters</button><a class="btn btn-outline-secondary" href="competitors.php">Reset</a></div></div></form>
<div class="small text-muted mb-2">Showing <?=$total?($offset+1):0?> to <?=min($offset+$perPage,$total)?> of <?=$total?> identities</div><section class="card border-0 shadow-sm"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Photo</th><th><a class="sortable" href="<?=e(dcsort('wdc_id',$sort,$order))?>">WDC ID</a></th><th><a class="sortable" href="<?=e(dcsort('name',$sort,$order))?>">Participant</a></th><th>Country</th><th class="category-stack">Registrations</th><th>Points / Results</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr id="wdc-<?=(int)$r['id']?>"><td><img class="photo" src="<?=e($r['photo_display']?:url('public/assets/img/default-competitor.svg'))?>" alt=""></td><td><code><?=e($r['identity_code'])?></code><?php if((int)$r['duplicate_count']):?><span class="badge text-bg-warning d-block mt-1">Possible duplicate</span><?php endif;?></td><td><strong><?=e($r['display_name'])?></strong><small class="d-block text-muted"><?=e(dclabel($r['entry_type']))?><?=$r['instagram']?' · @'.e(ltrim((string)$r['instagram'],'@')):''?></small></td><td><?=e($r['country_display']?:'—')?><?=$r['gender']?'<small class="d-block text-muted">'.e(dclabel($r['gender'])).'</small>':''?></td><td class="category-stack"><?php foreach(array_filter(explode(';;',(string)$r['registered_categories'])) as $item):$bits=explode('|',$item);?><span class="category-chip"><strong><?=e($bits[0]??'')?></strong><small class="text-muted"> · <?=e(dclabel($bits[1]??''))?> · <?=e(dclabel($bits[2]??''))?></small></span><?php endforeach;?><?php if(!(int)$r['registration_count']):?><span class="text-muted">No active registration</span><?php endif;?><small class="d-block text-muted mt-1"><?=e(str_replace(';;',' · ',(string)$r['registered_events']))?></small></td><td><strong><?=e((string)(float)$r['championship_points'])?> pts</strong><small class="d-block text-muted"><?=(int)$r['published_entries']?> published result(s)</small></td><td><span class="badge text-bg-<?=$r['status']==='active'?'success':'secondary'?>"><?=e(ucfirst($r['status']))?></span></td><td><div class="actions"><?php if(Auth::can('competitors.edit')):?><a class="btn btn-sm btn-dark" href="competitor-edit.php?id=<?=(int)$r['id']?>">Edit WDC</a><a class="btn btn-sm btn-outline-primary" href="photo-adjust.php?id=<?=(int)$r['id']?>">Adjust photo</a><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8" class="text-center text-muted py-5">No Dance Cup competitors match the selected filters.</td></tr><?php endif;?></tbody></table></div></section><?php if($pages>1):?><nav class="mt-3"><ul class="pagination"><?php for($i=1;$i<=$pages;$i++):?><li class="page-item <?=$i===$page?'active':''?>"><a class="page-link" href="<?=e(dcq(['page'=>$i]))?>"><?=$i?></a></li><?php endfor;?></ul></nav><?php endif;?></main></body></html>
